static uint8_t char_to_tile(char c) {
    switch (c) {
    case '#': return T_SOLID;
    case 'R': return T_BRICK;
    case '=': return T_PLAT;
    case '^': return T_SPIKE;
    case 'D': return T_DOOR;
    case 'M': return T_POST;
    case 'G': return T_GRASS;
    case 'L': return T_LEAF;
    case 'B': return T_EMPTY; /* ball is sprite/pickup */
    case 'P': return T_EMPTY;
    case 'E': return T_EMPTY;
    default:  return T_EMPTY;
    }
}

static bool tile_solid(uint8_t t) {
    return t == T_SOLID || t == T_BRICK || t == T_GRASS || t == T_DOOR || t == T_POST;
}

static bool tile_platform(uint8_t t) {
    return t == T_PLAT;
}

static bool tile_hazard(uint8_t t) {
    return t == T_SPIKE;
}

static uint8_t tile_at_px(int16_t x, int16_t y) {
    int16_t tx, ty;
    /* Convert OAM pixel to BG tile */
    tx = (x - 8) >> 3;
    ty = (y - 16) >> 3;
    if (tx < 0 || ty < 0 || tx >= ROOM_W || ty >= ROOM_H) {
        return T_SOLID;
    }
    return map[(uint8_t)ty * ROOM_W + (uint8_t)tx];
}

static void load_tiles(void) {
    set_bkg_data(T_EMPTY, 1u, tile_empty);
    set_bkg_data(T_SOLID, 1u, tile_solid);
    set_bkg_data(T_SPIKE, 1u, tile_spike);
    set_bkg_data(T_PLAT, 1u, tile_plat);
    set_bkg_data(T_DOOR, 1u, tile_door);
    set_bkg_data(T_BALL, 1u, tile_ball);
    set_bkg_data(T_POST, 1u, tile_post);
    set_bkg_data(T_GRASS, 1u, tile_grass);
    set_bkg_data(T_BRICK, 1u, tile_brick);
    set_bkg_data(T_LEAF, 1u, tile_leaf);
    /* Sprite tiles share IDs via set_sprite_data at 0 */
    set_sprite_data(0u, 1u, tile_player);
    set_sprite_data(1u, 1u, tile_ball);
    set_sprite_data(2u, 1u, tile_enemy);
}

static void hide_sprite(uint8_t s) {
    move_sprite(s, 0u, 0u);
}

static void parse_room(uint8_t r) {
    const char *src;
    uint8_t i, x, y;
    char c;

    src = room_maps[r];
    enemy_count = 0u;
    ball_alive = false;
    ball_held = false;
    holding_ball = false;
    has_goal = false;
    door_x = 18u;
    door_y = 11u;
    spawn_x = 2u;
    spawn_y = 14u;

    for (i = 0u; i < ROOM_W * ROOM_H; ++i) {
        c = src[i];
        x = (uint8_t)(i % ROOM_W);
        y = (uint8_t)(i / ROOM_W);
        map[i] = char_to_tile(c);

        if (c == 'P') {
            spawn_x = x;
            spawn_y = y;
        } else if (c == 'D') {
            door_x = x;
            door_y = y;
            map[i] = T_DOOR;
        } else if (c == 'M') {
            goal_x = x;
            goal_y = y;
            has_goal = true;
            map[i] = T_POST;
        } else if (c == 'B') {
            ball_alive = true;
            ball_held = false;
            ball_tile_x = x;
            ball_tile_y = y;
            bx = (int16_t)(x * 8 + 8);
            by = (int16_t)(y * 8 + 16);
            bvx = 0;
            bvy = 0;
        } else if (c == 'E' && enemy_count < MAX_ENEMIES) {
            ex[enemy_count] = (int16_t)(x * 8 + 8);
            ey[enemy_count] = (int16_t)(y * 8 + 16);
            /* Non-deterministic patrol direction after seed; default before seed */
            evx[enemy_count] = (enemy_count & 1u) ? (int8_t)1 : (int8_t)-1;
            estun[enemy_count] = 0u;
            ealive[enemy_count] = true;
            ++enemy_count;
        }
    }

    set_bkg_tiles(0u, 0u, ROOM_W, ROOM_H, map);
}

static void respawn_player(void) {
    px = (int16_t)(spawn_x * 8 + 8);
    py = (int16_t)(spawn_y * 8 + 16);
    pvx = 0;
    pvy = 0;
    facing = 1;
    on_ground = false;
    on_wall = false;
    wall_dir = 0;
    coyote = 0u;
    jump_buf = 0u;
    a_held = false;
    holding_ball = false;
    ball_held = false;
    /* Reset ball to spawn if not held in world mid-throw — full room reset */
    if (ball_alive || true) {
        /* restore ball pickup if room had one */
        {
            const char *src = room_maps[room];
            uint8_t i;
            ball_alive = false;
            for (i = 0u; i < ROOM_W * ROOM_H; ++i) {
                if (src[i] == 'B') {
                    ball_alive = true;
                    ball_held = false;
                    ball_tile_x = (uint8_t)(i % ROOM_W);
                    ball_tile_y = (uint8_t)(i / ROOM_W);
                    bx = (int16_t)(ball_tile_x * 8 + 8);
                    by = (int16_t)(ball_tile_y * 8 + 16);
                    bvx = 0;
                    bvy = 0;
                    break;
                }
            }
        }
    }
    /* Reset enemies */
    {
        const char *src = room_maps[room];
        uint8_t i, e;
        e = 0u;
        for (i = 0u; i < ROOM_W * ROOM_H; ++i) {
            if (src[i] == 'E' && e < MAX_ENEMIES) {
                ex[e] = (int16_t)((i % ROOM_W) * 8 + 8);
                ey[e] = (int16_t)((i / ROOM_W) * 8 + 16);
                if (seeded) {
                    evx[e] = ((int8_t)(rand() & 1)) ? (int8_t)1 : (int8_t)-1;
                } else {
                    evx[e] = (e & 1u) ? (int8_t)1 : (int8_t)-1;
                }
                estun[e] = 0u;
                ealive[e] = true;
                ++e;
            }
        }
        enemy_count = e;
    }
}

