    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    /* DMG: pale green-leaning palette (light background) */
    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    OBP1_REG = 0xD2u;
    NR52_REG = 0u;

    LCDC_REG = 0x40u;

    if (_cpu == CGB_TYPE) {
        set_bkg_palette(0u, 1u, bkg_palettes);
        set_sprite_palette(0u, 3u, obj_palettes);
    }

    load_tiles();

