static void sound_init(void) {
    NR52_REG = 0x80u;
    NR51_REG = 0xFFu;
    NR50_REG = 0x77u;
}

static void sfx_beep(void) {
    NR10_REG = 0x00u;
    NR11_REG = 0x80u;
    NR12_REG = 0xF1u;
    NR13_REG = 0x83u;
    NR14_REG = 0x87u;
}

static void sfx_boom(void) {
    NR41_REG = 0x00u;
    NR42_REG = 0xF3u;
    NR43_REG = 0x54u;
    NR44_REG = 0x80u;
}

static void sfx_jingle(void) {
    static const uint16_t notes[4] = {1797u, 1849u, 1881u, 1923u};
    uint8_t i, f;
    for (i = 0u; i < 4u; ++i) {
        NR21_REG = 0x80u;
        NR22_REG = 0xF2u;
        NR23_REG = (uint8_t)notes[i];
        NR24_REG = (uint8_t)(0x80u | (notes[i] >> 8));
        for (f = 0u; f < 8u; ++f) {
            wait_vbl_done();
        }
    }
}

static void sfx_jump(void) {
    NR10_REG = 0x15u;
    NR11_REG = 0x40u;
    NR12_REG = 0xF2u;
    NR13_REG = 0xC0u;
    NR14_REG = 0x85u;
}

static void sfx_throw(void) {
    NR10_REG = 0x00u;
    NR11_REG = 0x80u;
    NR12_REG = 0xD1u;
    NR13_REG = 0x20u;
    NR14_REG = 0x86u;
}

static uint8_t char_to_tile(char c) {
    switch (c) {
    case '#': return T_SOLID;
    case 'R': return T_BRICK;
    case '=': return T_PLAT;
    case '^': return T_SPIKE;
    case 'D': return T_DOOR;
    case 'M': return T_POST;
    case 'G': return T_GRASS;
    case 'L': return T_LEAF;
    case 'B': return T_EMPTY; /* ball is sprite/pickup */
    case 'P': return T_EMPTY;
    case 'E': return T_EMPTY;
    default:  return T_EMPTY;
    }
}

static bool tile_solid(uint8_t t) {
    return t == T_SOLID || t == T_BRICK || t == T_GRASS || t == T_DOOR || t == T_POST;
}

static bool tile_platform(uint8_t t) {
    return t == T_PLAT;
}

static bool tile_hazard(uint8_t t) {
    return t == T_SPIKE;
}

static uint8_t tile_at_px(int16_t x, int16_t y) {
    int16_t tx, ty;
    /* Convert OAM pixel to BG tile */
    tx = (x - 8) >> 3;
    ty = (y - 16) >> 3;
    if (tx < 0 || ty < 0 || tx >= ROOM_W || ty >= ROOM_H) {
        return T_SOLID;
    }
    return map[(uint8_t)ty * ROOM_W + (uint8_t)tx];
}

static void load_tiles(void) {
    set_bkg_data(T_EMPTY, 1u, tile_empty);
    set_bkg_data(T_SOLID, 1u, tile_solid);
    set_bkg_data(T_SPIKE, 1u, tile_spike);
    set_bkg_data(T_PLAT, 1u, tile_plat);
    set_bkg_data(T_DOOR, 1u, tile_door);
    set_bkg_data(T_BALL, 1u, tile_ball);
    set_bkg_data(T_POST, 1u, tile_post);
    set_bkg_data(T_GRASS, 1u, tile_grass);
    set_bkg_data(T_BRICK, 1u, tile_brick);
    set_bkg_data(T_LEAF, 1u, tile_leaf);
    /* Sprite tiles share IDs via set_sprite_data at 0 */
    set_sprite_data(0u, 1u, tile_player);
    set_sprite_data(1u, 1u, tile_ball);
    set_sprite_data(2u, 1u, tile_enemy);
}

static void hide_sprite(uint8_t s) {
    move_sprite(s, 0u, 0u);
}

static void parse_room(uint8_t r) {
    const char *src;
    uint8_t i, x, y;
    char c;

    src = room_maps[r];
    enemy_count = 0u;
    ball_alive = false;
    ball_held = false;
    holding_ball = false;
    has_goal = false;
    door_x = 18u;
    door_y = 11u;
    spawn_x = 2u;
    spawn_y = 14u;

    for (i = 0u; i < ROOM_W * ROOM_H; ++i) {
        c = src[i];
        x = (uint8_t)(i % ROOM_W);
        y = (uint8_t)(i / ROOM_W);
        map[i] = char_to_tile(c);

        if (c == 'P') {
            spawn_x = x;
            spawn_y = y;
        } else if (c == 'D') {
            door_x = x;
            door_y = y;
            map[i] = T_DOOR;
        } else if (c == 'M') {
            goal_x = x;
            goal_y = y;
            has_goal = true;
            map[i] = T_POST;
        } else if (c == 'B') {
            ball_alive = true;
            ball_held = false;
            ball_tile_x = x;
            ball_tile_y = y;
            bx = (int16_t)(x * 8 + 8);
            by = (int16_t)(y * 8 + 16);
            bvx = 0;
            bvy = 0;
        } else if (c == 'E' && enemy_count < MAX_ENEMIES) {
            ex[enemy_count] = (int16_t)(x * 8 + 8);
            ey[enemy_count] = (int16_t)(y * 8 + 16);
            /* Non-deterministic patrol direction after seed; default before seed */
            evx[enemy_count] = (enemy_count & 1u) ? (int8_t)1 : (int8_t)-1;
            estun[enemy_count] = 0u;
            ealive[enemy_count] = true;
            ++enemy_count;
        }
    }

    set_bkg_tiles(0u, 0u, ROOM_W, ROOM_H, map);
}

static void respawn_player(void) {
    px = (int16_t)(spawn_x * 8 + 8);
    py = (int16_t)(spawn_y * 8 + 16);
    pvx = 0;
    pvy = 0;
    facing = 1;
    on_ground = false;
    on_wall = false;
    wall_dir = 0;
    coyote = 0u;
    jump_buf = 0u;
    a_held = false;
    holding_ball = false;
    ball_held = false;
    /* Reset ball to spawn if not held in world mid-throw — full room reset */
    if (ball_alive || true) {
        /* restore ball pickup if room had one */
        {
            const char *src = room_maps[room];
            uint8_t i;
            ball_alive = false;
            for (i = 0u; i < ROOM_W * ROOM_H; ++i) {
                if (src[i] == 'B') {
                    ball_alive = true;
                    ball_held = false;
                    ball_tile_x = (uint8_t)(i % ROOM_W);
                    ball_tile_y = (uint8_t)(i / ROOM_W);
                    bx = (int16_t)(ball_tile_x * 8 + 8);
                    by = (int16_t)(ball_tile_y * 8 + 16);
                    bvx = 0;
                    bvy = 0;
                    break;
                }
            }
        }
    }
    /* Reset enemies */
    {
        const char *src = room_maps[room];
        uint8_t i, e;
        e = 0u;
        for (i = 0u; i < ROOM_W * ROOM_H; ++i) {
            if (src[i] == 'E' && e < MAX_ENEMIES) {
                ex[e] = (int16_t)((i % ROOM_W) * 8 + 8);
                ey[e] = (int16_t)((i / ROOM_W) * 8 + 16);
                if (seeded) {
                    evx[e] = ((int8_t)(rand() & 1)) ? (int8_t)1 : (int8_t)-1;
                } else {
                    evx[e] = (e & 1u) ? (int8_t)1 : (int8_t)-1;
                }
                estun[e] = 0u;
                ealive[e] = true;
                ++e;
            }
        }
        enemy_count = e;
    }
}

static void initialize_video(void) {
    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    /* DMG: pale green-leaning palette (light background) */
    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    OBP1_REG = 0xD2u;
    NR52_REG = 0u;

    LCDC_REG = 0x40u;

    if (_cpu == CGB_TYPE) {
        set_bkg_palette(0u, 1u, bkg_palettes);
        set_sprite_palette(0u, 3u, obj_palettes);
    }

    load_tiles();

    set_sprite_tile(SPR_PLAYER, 0u);
    set_sprite_tile(SPR_BALL, 1u);
    set_sprite_tile(SPR_ENEMY0, 2u);
    set_sprite_tile(SPR_ENEMY1, 2u);
    set_sprite_prop(SPR_PLAYER, 0u);
    set_sprite_prop(SPR_BALL, 1u);
    set_sprite_prop(SPR_ENEMY0, 2u);
    set_sprite_prop(SPR_ENEMY1, 2u);

    SPRITES_8x8;
    SHOW_BKG;
    SHOW_SPRITES;
    DISPLAY_ON;
}

static bool solid_at(int16_t x, int16_t y) {
    uint8_t t = tile_at_px(x, y);
    return tile_solid(t);
}

static bool blocks_at(int16_t x, int16_t y, int8_t vy_sense) {
    uint8_t t = tile_at_px(x, y);
    if (tile_solid(t)) {
        return true;
    }
    /* One-way platforms only when falling onto top */
    if (vy_sense > 0 && tile_platform(t)) {
        /* Only collide near top of tile */
        int16_t ty = (y - 16) >> 3;
        int16_t top = (int16_t)(ty * 8 + 16);
        if (y >= top && y < top + 4) {
            return true;
        }
    }
    return false;
}

static bool player_rect_blocked(int16_t nx, int16_t ny, int8_t vy_sense) {
    /* Sample corners and mid edges */
    int16_t x0 = nx;
    int16_t x1 = (int16_t)(nx + PW - 1);
    int16_t y0 = ny;
    int16_t y1 = (int16_t)(ny + PH - 1);
    if (blocks_at(x0, y0, vy_sense) || blocks_at(x1, y0, vy_sense) ||
        blocks_at(x0, y1, vy_sense) || blocks_at(x1, y1, vy_sense) ||
        blocks_at((int16_t)((x0 + x1) >> 1), y1, vy_sense)) {
        return true;
    }
    return false;
}

static bool hazard_at_player(void) {
    int16_t x0 = px;
    int16_t x1 = (int16_t)(px + PW - 1);
    int16_t y0 = py;
    int16_t y1 = (int16_t)(py + PH - 1);
    if (tile_hazard(tile_at_px(x0, y1)) || tile_hazard(tile_at_px(x1, y1)) ||
        tile_hazard(tile_at_px(x0, y0)) || tile_hazard(tile_at_px(x1, y0))) {
        return true;
    }
    return false;
}

static bool aabb(int16_t ax, int16_t ay, int16_t aw, int16_t ah,
                 int16_t bx_, int16_t by_, int16_t bw, int16_t bh) {
    return ax < bx_ + bw && ax + aw > bx_ && ay < by_ + bh && ay + ah > by_;
}

static void try_seed(void) {
    if (!seeded) {
        initrand(DIV_REG);
        seeded = true;
        /* Vary enemy directions once seed is live */
        {
            uint8_t e;
            for (e = 0u; e < enemy_count; ++e) {
                evx[e] = ((int8_t)(rand() & 1)) ? (int8_t)1 : (int8_t)-1;
            }
        }
        /* Slight spawn jitter on ball if present and free */
        if (ball_alive && !ball_held && bvx == 0 && bvy == 0) {
            bx = (int16_t)(bx + (int8_t)((rand() % 5) - 2));
        }
    }
}

static void throw_ball(void) {
    if (!holding_ball) {
        return;
    }
    holding_ball = false;
    ball_held = false;
    ball_alive = true;
    bx = (int16_t)(px + (facing > 0 ? 8 : -4));
    by = (int16_t)(py - 2);
    bvx = (int8_t)(facing * (int8_t)(3 + (seeded ? (rand() & 1) : 0)));
    bvy = -2;
    sfx_throw();
}

static void update_ball(void) {
    uint8_t e;
    if (holding_ball) {
        bx = (int16_t)(px + (facing > 0 ? 6 : -2));
        by = (int16_t)(py - 4);
        move_sprite(SPR_BALL, (uint8_t)bx, (uint8_t)by);
        return;
    }
    if (!ball_alive) {
        hide_sprite(SPR_BALL);
        return;
    }

    /* Pickup when still */
    if (bvx == 0 && bvy == 0) {
        if (aabb(px, py, PW, PH, bx, by, 8, 8)) {
            holding_ball = true;
            ball_held = true;
            sfx_beep();
        }
        move_sprite(SPR_BALL, (uint8_t)bx, (uint8_t)by);
        return;
    }

    /* Fly with gravity */
    bvy += 1;
    if (bvy > 4) {
        bvy = 4;
    }

    bx = (int16_t)(bx + bvx);
    if (solid_at(bx, (int16_t)(by + 4)) || solid_at((int16_t)(bx + 7), (int16_t)(by + 4))) {
        bvx = (int8_t)-bvx;
        bx = (int16_t)(bx + bvx);
    }
    by = (int16_t)(by + bvy);
    if (bvy > 0 && (solid_at((int16_t)(bx + 2), (int16_t)(by + 7)) ||
                    solid_at((int16_t)(bx + 5), (int16_t)(by + 7)))) {
        /* Rest on ground */
        bvx = 0;
        bvy = 0;
        /* Snap up out of floor */
        while (solid_at((int16_t)(bx + 2), (int16_t)(by + 7)) ||
               solid_at((int16_t)(bx + 5), (int16_t)(by + 7))) {
            --by;
        }
    }
    if (by > WORLD_BOTTOM || bx < 0 || bx > 168) {
        /* Respawn ball at original tile */
        bx = (int16_t)(ball_tile_x * 8 + 8);
        by = (int16_t)(ball_tile_y * 8 + 16);
        bvx = 0;
        bvy = 0;
    }

    /* Stun enemies on hit */
    for (e = 0u; e < enemy_count; ++e) {
        if (ealive[e] && estun[e] == 0u &&
            aabb(bx, by, 8, 8, ex[e], ey[e], 8, 8)) {
            estun[e] = 120u;
            bvx = (int8_t)-bvx;
            sfx_beep();
        }
    }

    move_sprite(SPR_BALL, (uint8_t)bx, (uint8_t)by);
}

static void update_enemies(void) {
    uint8_t e;
    int16_t nx;
    for (e = 0u; e < enemy_count; ++e) {
        if (!ealive[e]) {
            hide_sprite((uint8_t)(SPR_ENEMY0 + e));
            continue;
        }
        if (estun[e] > 0u) {
            --estun[e];
            /* Flash by hiding every other frame */
            if ((frame & 2u) != 0u) {
                hide_sprite((uint8_t)(SPR_ENEMY0 + e));
            } else {
                move_sprite((uint8_t)(SPR_ENEMY0 + e), (uint8_t)ex[e], (uint8_t)ey[e]);
            }
            continue;
        }
        nx = (int16_t)(ex[e] + evx[e]);
        /* Turn at walls or edges */
        if (solid_at(nx, (int16_t)(ey[e] + 4)) ||
            solid_at((int16_t)(nx + 7), (int16_t)(ey[e] + 4)) ||
            !solid_at((int16_t)(nx + 4), (int16_t)(ey[e] + 9))) {
            evx[e] = (int8_t)-evx[e];
            nx = (int16_t)(ex[e] + evx[e]);
        }
        ex[e] = nx;
        move_sprite((uint8_t)(SPR_ENEMY0 + e), (uint8_t)ex[e], (uint8_t)ey[e]);
    }
    /* Hide unused enemy sprites */
    for (; e < MAX_ENEMIES; ++e) {
        hide_sprite((uint8_t)(SPR_ENEMY0 + e));
    }
}

static bool enemy_hit_player(void) {
    uint8_t e;
    for (e = 0u; e < enemy_count; ++e) {
        if (ealive[e] && estun[e] == 0u &&
            aabb(px, py, PW, PH, ex[e], ey[e], 8, 8)) {
            return true;
        }
    }
    return false;
}

static bool at_exit(void) {
    int16_t cx = (int16_t)(px + 4);
    int16_t cy = (int16_t)(py + 4);
    uint8_t t = tile_at_px(cx, cy);
    if (room < 2u) {
        return t == T_DOOR ||
               aabb(px, py, PW, PH,
                    (int16_t)(door_x * 8 + 8), (int16_t)(door_y * 8 + 16), 8, 8);
    }
    /* Final room: touch mailbox */
    return has_goal &&
           aabb(px, py, PW, PH,
                (int16_t)(goal_x * 8 + 8), (int16_t)(goal_y * 8 + 16), 8, 12);
}

static void start_room(uint8_t r) {
    room = r;
    parse_room(r);
    respawn_player();
    move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
}

/* Returns 0 playing, 2 win, 3 loss */
static uint8_t update_player(uint8_t keys) {
    int8_t input_x = 0;
    int16_t nx, ny;
    bool want_jump;
    bool wall_l, wall_r;

    if ((keys & J_LEFT) != 0u) {
        input_x = -1;
        facing = -1;
    } else if ((keys & J_RIGHT) != 0u) {
        input_x = 1;
        facing = 1;
    }

    /* Horizontal velocity */
    if (input_x != 0) {
        pvx = (int8_t)(input_x * 2);
    } else {
        pvx = 0;
    }

    /* Gravity / wall slide */
    wall_l = solid_at((int16_t)(px - 1), (int16_t)(py + 2)) ||
             solid_at((int16_t)(px - 1), (int16_t)(py + 6));
    wall_r = solid_at((int16_t)(px + PW), (int16_t)(py + 2)) ||
             solid_at((int16_t)(px + PW), (int16_t)(py + 6));
    on_wall = !on_ground && ((wall_l && input_x < 0) || (wall_r && input_x > 0));
    if (on_wall) {
        wall_dir = wall_l ? (int8_t)-1 : (int8_t)1;
        if (pvy > 1) {
            pvy = 1; /* slide */
        }
    } else {
        wall_dir = 0;
    }

    if (!on_ground) {
        if (!on_wall) {
            pvy += 1;
            if (pvy > 5) {
                pvy = 5;
            }
        } else if (pvy < 1) {
            pvy += 1;
        }
    } else {
        pvy = 0;
    }

    want_jump = ((keys & J_A) != 0u);
    if (want_jump && !a_held) {
        jump_buf = 6u;
    }
    a_held = want_jump;

    if (jump_buf > 0u) {
        --jump_buf;
        if (on_ground || coyote > 0u) {
            pvy = -5;
            on_ground = false;
            coyote = 0u;
            jump_buf = 0u;
            sfx_jump();
        } else if (on_wall) {
            pvy = -5;
            pvx = (int8_t)(-wall_dir * 3);
            on_wall = false;
            jump_buf = 0u;
            facing = (int8_t)-wall_dir;
            sfx_jump();
        }
    }

    /* Throw with Down */
    if ((keys & J_DOWN) != 0u && holding_ball) {
        throw_ball();
    }

    /* Move X */
    nx = (int16_t)(px + pvx);
    if (pvx != 0) {
        if (!player_rect_blocked(nx, py, pvy)) {
            px = nx;
        } else {
            /* Nudge flush */
            if (pvx > 0) {
                while (!player_rect_blocked((int16_t)(px + 1), py, pvy)) {
                    ++px;
                }
            } else {
                while (!player_rect_blocked((int16_t)(px - 1), py, pvy)) {
                    --px;
                }
            }
            pvx = 0;
        }
    }

    /* Move Y */
    ny = (int16_t)(py + pvy);
    on_ground = false;
    if (pvy >= 0) {
        if (!player_rect_blocked(px, ny, 1)) {
            py = ny;
        } else {
            while (!player_rect_blocked(px, (int16_t)(py + 1), 1)) {
                ++py;
            }
            on_ground = true;
            pvy = 0;
            coyote = 6u;
        }
    } else {
        if (!player_rect_blocked(px, ny, -1)) {
            py = ny;
        } else {
            while (!player_rect_blocked(px, (int16_t)(py - 1), -1)) {
                --py;
            }
            pvy = 0;
        }
    }

    if (on_ground) {
        coyote = 6u;
    } else if (coyote > 0u) {
        --coyote;
    }

    /* Fall out of world */
    if (py > (int16_t)WORLD_BOTTOM) {
        return 3u;
    }

    if (hazard_at_player() || enemy_hit_player()) {
        return 3u;
    }

    if (at_exit()) {
        if (room >= 2u) {
            return 2u;
        }
        sfx_beep();
        start_room((uint8_t)(room + 1u));
        /* Brief i-frames not needed; new room */
    }

    move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
    return 0u;
}

void main(void) {
    uint8_t keys;
    uint8_t st;

    wait_vbl_done();

    seeded = false;
    frame = 0u;
    room = 0u;

    initialize_video();
    sound_init();
    start_room(0u);
    NOVA_STATE = 1u;

    st = 0u;
    while (st == 0u) {
        keys = joypad();
        if (keys != 0u) {
            try_seed();
        }

        st = update_player(keys);
        if (st == 0u) {
            update_ball();
            update_enemies();
        }

        ++frame;
        wait_vbl_done();
    }

    NOVA_STATE = st;
    if (st == 2u) {
        sfx_jingle();
    } else {
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

details.old_string:
#include <gb/gb.h>
#include <stdbool.h>
#include <stdint.h>

#include "assets.h"

enum {
    TILE_EMPTY = 0x80u,
    TILE_BRICK_LEFT = 0x88u,
    TILE_BRICK_RIGHT = 0x89u,
    TILE_PADDLE_LEFT = 0x8Cu,
    TILE_PADDLE_MIDDLE = 0x8Du,
    TILE_PADDLE_RIGHT = 0x8Eu,
    TILE_BALL = 0x8Fu,

    BALL_SPRITE = 0u,
    PADDLE_LEFT_SPRITE = 1u,
    PADDLE_MIDDLE_SPRITE = 2u,
    PADDLE_RIGHT_SPRITE = 3u,

    PADDLE_Y = 0x98u,
    PADDLE_MIN_X = 0x08u,
    PADDLE_MAX_X = 0x90u,
    PADDLE_INITIAL_X = 0x4Cu,
    BALL_INITIAL_X = 0x32u,
    BALL_INITIAL_Y = 0x78u,
    BALL_LOSS_Y = 0x9Au,
    INITIAL_BRICK_COUNT = 39u
};

/*
 * Nova arcade protocol: one byte at a fixed WRAM address the arcade polls to
 * detect run state. The linker can't move it because it's an absolute pointer,
 * not a variable. 1 = run started, 2 = won, 3 = lost. Every game the pipeline
 * ships MUST keep these three writes intact.
 */
#define NOVA_STATE (*(volatile uint8_t *)0xCF00)

/*
 * These six values correspond to the original ROM's globals at $C0A0-$C0A5.
 * Positions use Game Boy OAM coordinates: visible X is X - 8 and visible Y
 * is Y - 16.
 */
static uint8_t paddle_x;
static uint8_t ball_x;
static uint8_t ball_y;
static int8_t ball_vx;
static int8_t ball_vy;
static uint8_t bricks_remaining;

/*
 * APU helpers. Reusable one-call sound effects on the Game Boy's channels.
 * Remixes should call these (retuning register values if a different pitch
 * or feel is wanted) instead of writing raw NRxx sequences at every new
 * sound moment. sound_init() must run once, after initialize_video(), which
 * powers the APU down like the original ROM did.
 */
static void sound_init(void) {
    NR52_REG = 0x80u; /* APU on; must be set before any other register */
    NR51_REG = 0xFFu; /* every channel to both output terminals */
    NR50_REG = 0x77u; /* max master volume, VIN off */
}

/* Short square blip on channel 1: paddle and brick hits. Non-blocking. */
static void sfx_beep(void) {
    NR10_REG = 0x00u; /* no sweep */
    NR11_REG = 0x80u; /* 50% duty */
    NR12_REG = 0xF1u; /* full volume, fast envelope decay */
    NR13_REG = 0x83u;
    NR14_REG = 0x87u; /* trigger, period 0x783 (~1050 Hz) */
}

/* Noise burst on channel 4: the loss thud. Non-blocking. */
static void sfx_boom(void) {
    NR41_REG = 0x00u;
    NR42_REG = 0xF3u; /* full volume, medium envelope decay */
    NR43_REG = 0x54u; /* mid-pitch noise */
    NR44_REG = 0x80u; /* trigger */
}

/* Rising four-note win arpeggio on channel 2. Blocks about half a second. */
static void sfx_jingle(void) {
    static const uint16_t notes[4] = {1797u, 1849u, 1881u, 1923u}; /* C5 E5 G5 C6 */
    uint8_t i;
    uint8_t frame;

    for (i = 0u; i < 4u; ++i) {
        NR21_REG = 0x80u; /* 50% duty */
        NR22_REG = 0xF2u; /* full volume, gentle decay */
        NR23_REG = (uint8_t)notes[i];
        NR24_REG = (uint8_t)(0x80u | (notes[i] >> 8)); /* trigger */
        for (frame = 0u; frame < 8u; ++frame) {
            wait_vbl_done();
        }
    }
}

static void draw_paddle(void) {
    move_sprite(PADDLE_LEFT_SPRITE, paddle_x, PADDLE_Y);
    move_sprite(PADDLE_MIDDLE_SPRITE, (uint8_t)(paddle_x + 8u), PADDLE_Y);
    move_sprite(PADDLE_RIGHT_SPRITE, (uint8_t)(paddle_x + 16u), PADDLE_Y);
}

static void move_paddle(int8_t delta) {
    int16_t next_x;

    if (delta == 0) {
        paddle_x = PADDLE_INITIAL_X;
    } else {
        next_x = (int16_t)paddle_x + delta;

        if (next_x < PADDLE_MIN_X) {
            next_x = PADDLE_MIN_X;
        } else if (next_x > PADDLE_MAX_X) {
            next_x = PADDLE_MAX_X;
        }

        paddle_x = (uint8_t)next_x;
    }

    draw_paddle();
}

static void remove_brick(uint8_t tile_x, uint8_t tile_y) {
    set_bkg_tile_xy(tile_x, tile_y, TILE_EMPTY);
    set_bkg_tile_xy((uint8_t)(tile_x + 1u), tile_y, TILE_EMPTY);
    --bricks_remaining;
    sfx_beep();
}

static bool overlaps_paddle(uint8_t candidate_x, uint8_t candidate_y) {
    int16_t ball_left;
    int16_t ball_right;
    int16_t paddle_left;
    int16_t paddle_right;

    if ((uint16_t)candidate_y + 5u < PADDLE_Y) {
        return false;
    }

    ball_left = candidate_x;
    ball_right = ball_left + 5;
    paddle_left = paddle_x;
    paddle_right = paddle_left + 24;

    /*
     * This intentionally preserves the ROM's slightly asymmetric right edge:
     * the ball's left sample is inclusive, while its right sample is strict.
     */
    return ((ball_left >= paddle_left) && (ball_left <= paddle_right)) ||
           ((ball_right >= paddle_left) && (ball_right < paddle_right));
}

static bool collides(int8_t delta_x, int8_t delta_y) {
    uint8_t candidate_x;
    uint8_t candidate_y;
    int16_t sample_x;
    int16_t sample_y;
    uint8_t tile_x;
    uint8_t tile_y;
    uint8_t tile;

    candidate_x = (uint8_t)(ball_x + delta_x);
    candidate_y = (uint8_t)(ball_y + delta_y);

    if (overlaps_paddle(candidate_x, candidate_y)) {
        sfx_beep();
        return true;
    }

    /*
     * The original uses a six-pixel collision span and chooses the leading
     * edge from the current global velocity. The X velocity may already have
     * been reversed by the horizontal probe earlier in this frame.
     */
    sample_x = candidate_x;
    sample_y = candidate_y;

    if (ball_vx > 0) {
        sample_x += 5;
    }
    if (ball_vy > 0) {
        sample_y += 5;
    }

    tile_x = (uint8_t)((sample_x - 8) >> 3);
    tile_y = (uint8_t)((sample_y - 16) >> 3);
    tile = get_bkg_tile_xy(tile_x, tile_y);

    if (tile == TILE_BRICK_LEFT) {
        remove_brick(tile_x, tile_y);
    } else if (tile == TILE_BRICK_RIGHT) {
        remove_brick((uint8_t)(tile_x - 1u), tile_y);
    }

    return tile != TILE_EMPTY;
}

static void initialize_video(void) {
    DISPLAY_OFF;

    SCX_REG = 0u;
    SCY_REG = 0u;
    WY_REG = 0u;
    WX_REG = 7u;
    STAT_REG = 0u;

    BGP_REG = 0xE4u;
    OBP0_REG = 0xE4u;
    OBP1_REG = 0x1Bu;
    NR52_REG = 0u;

    /*
     * Bit 4 remains clear so background tile IDs $80-$FF use the signed
     * $8800 tile-data region. SHOW_BKG, SHOW_SPRITES, and DISPLAY_ON below
     * turn this into the original final LCDC value, $C3.
     */
    LCDC_REG = 0x40u;

    set_bkg_data(0x80u, BREAKOUT_TILE_COUNT, breakout_tile_data);
    set_bkg_tiles(
        0u,
        0u,
        BREAKOUT_MAP_WIDTH,
        BREAKOUT_MAP_HEIGHT,
        breakout_background_map
    );

    set_sprite_tile(BALL_SPRITE, TILE_BALL);
    set_sprite_tile(PADDLE_LEFT_SPRITE, TILE_PADDLE_LEFT);
    set_sprite_tile(PADDLE_MIDDLE_SPRITE, TILE_PADDLE_MIDDLE);
    set_sprite_tile(PADDLE_RIGHT_SPRITE, TILE_PADDLE_RIGHT);

    SPRITES_8x8;
    SHOW_BKG;
    SHOW_SPRITES;
    DISPLAY_ON;
}

static void initialize_game(void) {
    paddle_x = PADDLE_INITIAL_X;
    ball_x = BALL_INITIAL_X;
    ball_y = BALL_INITIAL_Y;
    ball_vx = 1;
    ball_vy = -1;
    bricks_remaining = INITIAL_BRICK_COUNT;

    move_paddle(0);
    move_sprite(BALL_SPRITE, ball_x, ball_y);
}

void main(void) {
    uint8_t keys;

    /*
     * The recovered CRT clears a larger runtime area than modern GBDK does.
     * Waiting one VBlank here aligns the first active gameplay frame with the
     * original ROM (frame 90 after reset in the deterministic SameBoy boot).
     */
    wait_vbl_done();

    initialize_video();
    sound_init();
    initialize_game();
    NOVA_STATE = 1u;

    while (bricks_remaining != 0u) {
        keys = joypad();

        if ((keys & J_LEFT) != 0u) {
            move_paddle(-2);
        } else if ((keys & J_RIGHT) != 0u) {
            move_paddle(2);
        }

        if (ball_y >= BALL_LOSS_Y) {
            break;
        }

        if (collides(ball_vx, 0)) {
            ball_vx = (int8_t)-ball_vx;
        }

        if (collides(0, ball_vy)) {
            ball_vy = (int8_t)-ball_vy;
        }

        ball_x = (uint8_t)(ball_x + ball_vx);
        ball_y = (uint8_t)(ball_y + ball_vy);
        move_sprite(BALL_SPRITE, ball_x, ball_y);
        wait_vbl_done();
    }

    /* The original silently idles forever after both a win and a loss. */
    NOVA_STATE = bricks_remaining == 0u ? 2u : 3u;
    if (bricks_remaining == 0u) {
        sfx_jingle();
    } else {
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

details.new_string:
// TITLE: Postie
// DESC: Three-room wall-jump platformer with throwable balls; green backdrop remix.
// CONTROLS: D-pad move/climb, A jump/wall-jump, Down throw ball
#include <gb/gb.h>
#include <gb/cgb.h>
#include <stdbool.h>
#include <stdint.h>
#include <rand.h>

#include "assets.h"

/* Nova arcade protocol: arcade polls this WRAM byte for run timing/end screen. */
#define NOVA_STATE (*(volatile uint8_t *)0xCF00)

enum {
    /* Custom tile IDs in signed region $8800 (LCDC bit4 clear) */
    T_EMPTY = 0x80u,
    T_SOLID = 0x81u,
    T_SPIKE = 0x82u,
    T_PLAT = 0x83u,
    T_DOOR = 0x84u,
    T_BALL = 0x85u,
    T_POST = 0x86u, /* mailbox / goal post */
    T_GRASS = 0x87u,
    T_BRICK = 0x88u,
    T_LEAF = 0x89u,

    SPR_PLAYER = 0u,
    SPR_BALL = 1u,
    SPR_ENEMY0 = 2u,
    SPR_ENEMY1 = 3u,

    /* Pixel sizes (OAM coords: visible = x-8, y-16) */
    PW = 8,
    PH = 8,
    ROOM_W = 20,
    ROOM_H = 18,

    /* World bounds in OAM coordinates */
    WORLD_LEFT = 8,
    WORLD_RIGHT = 160,  /* exclusive max for left edge + width checks */
    WORLD_TOP = 16,
    WORLD_BOTTOM = 144 + 16,

    MAX_ENEMIES = 2,
    MAX_PICKUPS = 2
};

/* Green CGB background + object palettes */
static const UWORD bkg_palettes[] = {
    RGB(0, 24, 8),   /* light green empty */
    RGB(0, 18, 4),   /* mid */
    RGB(0, 10, 2),   /* dark */
    RGB(0, 4, 0)     /* deepest */
};

static const UWORD obj_palettes[] = {
    RGB(31, 31, 31),
    RGB(0, 20, 6),
    RGB(31, 20, 0),
    RGB(0, 0, 0),
    /* palette 1: ball */
    RGB(31, 31, 31),
    RGB(31, 28, 10),
    RGB(20, 12, 0),
    RGB(0, 0, 0),
    /* palette 2: enemy */
    RGB(31, 31, 31),
    RGB(31, 8, 8),
    RGB(16, 0, 0),
    RGB(0, 0, 0)
};

/*
 * 2bpp tiles (16 bytes each). Designed for green BGP/CGB look.
 * Bit pairs: 00 empty light, 01 mid, 10 dark, 11 blackish.
 */
static const uint8_t tile_empty[16] = {
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};
static const uint8_t tile_solid[16] = {
