rawInput.old_string:
    /* Fall out of world */
    if (py > (int16_t)WORLD_BOTTOM) {
        return 3u;
    }

    if (hazard_at_player() || enemy_hit_player()) {
        return 3u;
    }

    if (at_exit()) {
        if (room >= 2u) {
            return 2u;
        }
        sfx_beep();
        start_room((uint8_t)(room + 1u));
        /* Brief i-frames not needed; new room */
    }

    move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
    return 0u;
}

rawInput.new_string:
    /* Death: spikes, enemies, or fall — instant room restart; out of lives = loss */
    if (py > (int16_t)WORLD_BOTTOM || hazard_at_player() || enemy_hit_player()) {
        sfx_boom();
        if (lives == 0u) {
            return 3u;
        }
        --lives;
        respawn_player();
        move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
        return 0u;
    }

    if (at_exit()) {
        if (room >= 2u) {
            return 2u;
        }
        sfx_beep();
        start_room((uint8_t)(room + 1u));
    }

    move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
    return 0u;
}

