/* Returns 0 playing, 2 win, 3 loss. Death instant-restarts room or spends a life. */
static uint8_t update_player(uint8_t keys) {
    int8_t input_x = 0;
    int16_t nx, ny;
    bool want_jump;
    bool wall_l, wall_r;

    if ((keys & J_LEFT) != 0u) {
        input_x = -1;
        facing = -1;
    } else if ((keys & J_RIGHT) != 0u) {
        input_x = 1;
        facing = 1;
    }

    /* Horizontal velocity */
    if (input_x != 0) {
        pvx = (int8_t)(input_x * 2);
    } else {
        pvx = 0;
    }

    /* Gravity / wall slide */
    wall_l = solid_at((int16_t)(px - 1), (int16_t)(py + 2)) ||
             solid_at((int16_t)(px - 1), (int16_t)(py + 6));
    wall_r = solid_at((int16_t)(px + PW), (int16_t)(py + 2)) ||
             solid_at((int16_t)(px + PW), (int16_t)(py + 6));
    on_wall = !on_ground && ((wall_l && input_x < 0) || (wall_r && input_x > 0));
    if (on_wall) {
        wall_dir = wall_l ? (int8_t)-1 : (int8_t)1;
        if (pvy > 1) {
            pvy = 1; /* slide */
        }
    } else {
        wall_dir = 0;
    }

    if (!on_ground) {
        if (!on_wall) {
            pvy += 1;
            if (pvy > 5) {
                pvy = 5;
            }
        } else if (pvy < 1) {
            pvy += 1;
        }
    } else {
        pvy = 0;
    }

    want_jump = ((keys & J_A) != 0u);
    if (want_jump && !a_held) {
        jump_buf = 6u;
    }
    a_held = want_jump;

    if (jump_buf > 0u) {
        --jump_buf;
        if (on_ground || coyote > 0u) {
            pvy = -6;
            on_ground = false;
            coyote = 0u;
            jump_buf = 0u;
            sfx_jump();
        } else if (on_wall) {
            pvy = -6;
            pvx = (int8_t)(-wall_dir * 3);
            on_wall = false;
            jump_buf = 0u;
            facing = (int8_t)-wall_dir;
            sfx_jump();
        }
    }

    /* Throw with Down */
    if ((keys & J_DOWN) != 0u && holding_ball) {
        throw_ball();
    }

    /* Move X */
    nx = (int16_t)(px + pvx);
    if (pvx != 0) {
        if (!player_rect_blocked(nx, py, pvy)) {
            px = nx;
        } else {
            /* Nudge flush */
            if (pvx > 0) {
                while (!player_rect_blocked((int16_t)(px + 1), py, pvy)) {
                    ++px;
                }
            } else {
                while (!player_rect_blocked((int16_t)(px - 1), py, pvy)) {
                    --px;
                }
            }
            pvx = 0;
        }
    }

    /* Move Y */
    ny = (int16_t)(py + pvy);
    on_ground = false;
    if (pvy >= 0) {
        if (!player_rect_blocked(px, ny, 1)) {
            py = ny;
        } else {
            while (!player_rect_blocked(px, (int16_t)(py + 1), 1)) {
                ++py;
            }
            on_ground = true;
            pvy = 0;
            coyote = 6u;
        }
    } else {
        if (!player_rect_blocked(px, ny, -1)) {
            py = ny;
        } else {
            while (!player_rect_blocked(px, (int16_t)(py - 1), -1)) {
                --py;
            }
            pvy = 0;
        }
    }

    if (on_ground) {
        coyote = 6u;
    } else if (coyote > 0u) {
        --coyote;
    }

    /* Death: spikes, enemies, or fall — instant room restart; out of lives = loss */
    if (py > (int16_t)WORLD_BOTTOM || hazard_at_player() || enemy_hit_player()) {
        sfx_boom();
        if (lives == 0u) {
            return 3u;
        }
        --lives;
        respawn_player();
        move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
        return 0u;
    }

    if (at_exit()) {
        if (room >= 2u) {
            return 2u;
        }
        sfx_beep();
        start_room((uint8_t)(room + 1u));
    }

    move_sprite(SPR_PLAYER, (uint8_t)px, (uint8_t)py);
    return 0u;
}

void main(void) {
    uint8_t keys;
    uint8_t st;

    wait_vbl_done();

    seeded = false;
    frame = 0u;
    room = 0u;
    lives = 3u;

    initialize_video();
    sound_init();
    start_room(0u);
    NOVA_STATE = 1u;

    st = 0u;
    while (st == 0u) {
        keys = joypad();
        if (keys != 0u) {
            try_seed();
        }

        st = update_player(keys);
        if (st == 0u) {
            update_ball();
            update_enemies();
        }

        ++frame;
        wait_vbl_done();
    }

    NOVA_STATE = st;
    if (st == 2u) {
        sfx_jingle();
    } else {
        sfx_boom();
    }
    while (true) {
        wait_vbl_done();
    }
}

