static uint8_t update_player(uint8_t keys) {
    int8_t input_x = 0;
    int16_t nx, ny;
    bool want_jump;
    bool wall_l, wall_r;

    if ((keys & J_LEFT) != 0u) {
        input_x = -1;
        facing = -1;
    } else if ((keys & J_RIGHT) != 0u) {
        input_x = 1;
        facing = 1;
