    if (on_wall) {
        wall_dir = wall_l ? (int8_t)-1 : (int8_t)1;
        if (pvy > 1) {
            pvy = 1; /* slide */
        }
    } else {
        wall_dir = 0;
    }

    if (!on_ground) {
        if (!on_wall) {
            pvy += 1;
            if (pvy > 5) {
                pvy = 5;
            }
        } else if (pvy < 1) {
            pvy += 1;
        }
    } else {
        pvy = 0;
    }

    want_jump = ((keys & J_A) != 0u);
    if (want_jump && !a_held) {
        jump_buf = 6u;
    }
    a_held = want_jump;

    if (jump_buf > 0u) {
        --jump_buf;
        if (on_ground || coyote > 0u) {
            pvy = -6;
            on_ground = false;
            coyote = 0u;
            jump_buf = 0u;
